const html = $input.first().json.data; 
const livresExtraits = [];
const morceauxDeCode = html.split('bookHorizontalTitlePolice');

for (let i = 1; i < morceauxDeCode.length; i++) {
    const morceau = morceauxDeCode[i];

    // 1. TITRE
    let titre = "Titre inconnu";
    const titreMatch = morceau.match(/>([^<]+)<\/h2>/);
    if (titreMatch && titreMatch[1]) titre = titreMatch[1].trim();

    // 2. AUTEUR
    let auteur = "Auteur inconnu";
    const auteurMatch = morceau.match(/bookHorizontalAuthorPolice[^>]*>([^<]+)<\/h3>/);
    if (auteurMatch && auteurMatch[1]) auteur = auteurMatch[1].trim();

    // 3. GENRE
    let genre = "Non renseigné";
    const genreMatch = morceau.match(/categoryObjectLibelle[^>]*>([^<]+)<\/p>/);
    if (genreMatch && genreMatch[1]) genre = genreMatch[1].trim();

    // 4. STATUT (Avec la nouvelle priorité !)
    let statut = "Non classé";

    // On analyse toutes les couleurs présentes d'un coup
    let possede = morceau.includes('rgb(60, 164, 255)') || morceau.includes('#3CA4FF');
    let lu = morceau.includes('rgb(92, 228, 92)') || morceau.includes('#5CE45C');
    let enCours = morceau.includes('rgb(213, 154, 237)') || morceau.includes('#D59AED');
    let souhait = morceau.includes('rgb(252, 169, 92)') || morceau.includes('#FCA95C');

    // On donne la priorité absolue à ce que tu possèdes ou as lu
    if (possede && lu) statut = "Possédé et Lu";
    else if (possede && enCours) statut = "Possédé et Je lis";
    else if (possede && !lu && !enCours) statut = "Possédé et Non lu";
    else if (!possede && lu) statut = "Non possédé mais Lu";
    else if (!possede && enCours) statut = "Non possédé mais Je lis";
    else if (souhait) statut = "Liste de souhait"; // Le souhait passe en dernier recours !

    // 5. CRÉATION DE L'ID UNIQUE
    const id_unique = (titre + auteur).replace(/[^a-zA-Z0-9]/g, "").toLowerCase();

    livresExtraits.push({
        id_unique: id_unique,
        titre: titre,
        auteur: auteur,
        genre: genre,
        statut: statut
    });
}

return livresExtraits.map(livre => ({ json: livre }));

const livres = $input.all().map(item => item.json);

let countSouhait = 0;
let countPossessionTotal = 0;
let countPossessionEtLu = 0;
let countNonPossessionEtLu = 0;

livres.forEach(livre => {
    // Liste de souhait
    if (livre.statut === "Liste de souhait") countSouhait++;

    // Total possédé : on englobe TOUT ce qu'on possède, peu importe si c'est lu, non lu, ou en cours
    if (livre.statut === "Possédé et Lu" || livre.statut === "Possédé et Non lu" || livre.statut === "Possédé et Je lis") {
        countPossessionTotal++;
    }

    // Les catégories précises
    if (livre.statut === "Possédé et Lu") countPossessionEtLu++;
    if (livre.statut === "Non possédé mais Lu") countNonPossessionEtLu++;
});

return [{
    json: {
        "Liste de souhait": countSouhait,
        "En possession (Total)": countPossessionTotal,
        "En possession et Lu": countPossessionEtLu,
        "Non possédé et Lu": countNonPossessionEtLu
    }
}];

const resultats = $input.first().json;

const categorieSery = {};
function extraireIdsCategorie(html, nomCat) {
    if (!html) return;
    const liens = html.matchAll(/href="\/[^\/]+\/serie\/([a-zA-Z0-9]+)"/g);
    for (const match of liens) {
        categorieSery[match[1]] = nomCat;
    }
}
extraireIdsCategorie(resultats["BD"], "BD");
extraireIdsCategorie(resultats["Comics"], "Comics");
extraireIdsCategorie(resultats["Mangas"], "Mangas");

const idsJaiPas = new Set();
if (resultats["JaiPas"]) {
    const liensJaiPas = resultats["JaiPas"].matchAll(/href="\/[^\/]+\/serie\/([a-zA-Z0-9]+)"/g);
    for (const match of liensJaiPas) { idsJaiPas.add(match[1]); }
}

const idsJai = new Set();
const vraisPossedes = {};
if (resultats["Jai"]) {
    const morceaux = resultats["Jai"].split('href="/');
    for (let i = 1; i < morceaux.length; i++) {
        if (!morceaux[i].includes('serie/')) continue;
        const idMatch = morceaux[i].match(/^[^\/]+\/serie\/([a-zA-Z0-9]+)"/);
        if (!idMatch) continue;
        const id_unique = idMatch[1];
        idsJai.add(id_unique);

        const albumsMatch = morceaux[i].match(/bb-l-text-size[^>]*>\s*([0-9]+)(?:\s*\/\s*[0-9]+)?\s*<\/div>\s*<div[^>]*>\s*albums?/i);
        if (albumsMatch) vraisPossedes[id_unique] = parseInt(albumsMatch[1], 10);
    }
}

const seriesExtraites = [];
const idsDejaTraites = new Set();
const pagesAAnalyser = [resultats["BD"], resultats["Comics"], resultats["Mangas"], resultats["Jai"], resultats["JaiPas"]];

for (const html of pagesAAnalyser) {
    if (!html) continue;

    const morceaux = html.split('href="/');
    for (let i = 1; i < morceaux.length; i++) {
        const morceau = morceaux[i];
        if (!morceau.includes('serie/')) continue;

        const idMatch = morceau.match(/^[^\/]+\/serie\/([a-zA-Z0-9]+)"/);
        if (!idMatch) continue;
        const id_unique = idMatch[1];

        if (idsDejaTraites.has(id_unique)) continue;
        idsDejaTraites.add(id_unique);

        const titreMatch = morceau.match(/fw-bold[^>]*>\s*([^<]+)\s*<\/div>/i);
        const titre = titreMatch ? titreMatch[1].trim() : "Titre inconnu";

        let albumsLus = 0;
        const lusMatch = morceau.match(/bb-l-text-size[^>]*>\s*([0-9]+)(?:\s*\/\s*[0-9]+)?\s*<\/div>\s*<div[^>]*>\s*lus?/i);
        if (lusMatch) albumsLus = parseInt(lusMatch[1], 10);

        // 🎯 LA CORRECTION MAGIQUE EST ICI 🎯
        let albumsPossedes = 0;
        if (vraisPossedes[id_unique] > 0) {
            // S'il y a un chiffre lu dans "J'ai", c'est la vérité absolue (Même si c'est aussi dans "J'ai pas")
            albumsPossedes = vraisPossedes[id_unique];
        } else if (idsJai.has(id_unique) && !idsJaiPas.has(id_unique)) {
            // Si la regex échoue mais que c'est uniquement dans "J'ai", on assure le coup avec 1
            albumsPossedes = 1; 
        } else {
            albumsPossedes = 0;
        }

        let statut = "Non classé";
        let albumsNonPossedesLu = 0;

        if (albumsPossedes > 0) {
            if (albumsLus > albumsPossedes) {
                albumsNonPossedesLu = albumsLus - albumsPossedes;
                statut = "Partiellement possédé";
            } else if (albumsLus === albumsPossedes) {
                statut = "Possédé et Lu";
            } else if (albumsLus > 0 && albumsLus < albumsPossedes) {
                statut = "Possédé et Je lis";
            } else if (albumsLus === 0) {
                statut = "Possédé et Non lu";
            }
        } else {
            if (albumsLus > 0) {
                albumsNonPossedesLu = albumsLus;
                statut = "Non possédé mais Lu";
            } else {
                statut = "Non possédé et Non lu";
            }
        }

        const categorie = categorieSery[id_unique] || "Autre";

        seriesExtraites.push({
            id_unique: id_unique, titre: titre, categorie: categorie,
            albums_possedes: albumsPossedes, albums_lus: albumsLus,
            albums_non_possedes_lu: albumsNonPossedesLu, statut: statut
        });
    }
}
return seriesExtraites.map(serie => ({ json: serie }));

// On récupère toutes les séries
const series = $input.all().map(item => item.json);

const stats = {
    "BD": { possedes: 0, possedes_lus: 0, non_possedes_lus: 0 },
    "Comics": { possedes: 0, possedes_lus: 0, non_possedes_lus: 0 },
    "Mangas": { possedes: 0, possedes_lus: 0, non_possedes_lus: 0 },
    "Autre": { possedes: 0, possedes_lus: 0, non_possedes_lus: 0 }
};

for (const s of series) {
    const cat = s.categorie || "Autre";

    if (!stats[cat]) {
        stats[cat] = { possedes: 0, possedes_lus: 0, non_possedes_lus: 0 };
    }

    stats[cat].possedes += (s.albums_possedes || 0);
    stats[cat].non_possedes_lus += (s.albums_non_possedes_lu || 0);

    const lusEtPossedes = (s.albums_lus || 0) - (s.albums_non_possedes_lu || 0);
    stats[cat].possedes_lus += lusEtPossedes;
}

const ligneGoogleSheet = {};

for (const cat of ["BD", "Comics", "Mangas", "Autre"]) {
    if (cat === "Autre" && stats[cat].possedes === 0 && stats[cat].non_possedes_lus === 0) continue;

    ligneGoogleSheet[`${cat} - Possédés`] = stats[cat].possedes;
    ligneGoogleSheet[`${cat} - Possédés et Lus`] = stats[cat].possedes_lus;
    ligneGoogleSheet[`${cat} - Non possédés et Lus`] = stats[cat].non_possedes_lus;
}

return [{ json: ligneGoogleSheet }];

