const resultats = $input.first().json;
const seriesMap = {};

// 1. On mémorise la catégorie (depuis les listes filtrées)
function extraireIdsCategorie(html, nomCat) {
    if (!html) return;
    const liens = html.matchAll(/href="\/[^\/]+\/serie\/([a-zA-Z0-9]+)"/g);
    for (const match of liens) {
        if (!seriesMap[match[1]]) {
            seriesMap[match[1]] = { id_unique: match[1], categorie: nomCat, titre: "Titre inconnu", albums_manquants: 0 };
        } else {
            seriesMap[match[1]].categorie = nomCat;
        }
    }
}
extraireIdsCategorie(resultats["BD"], "BD");
extraireIdsCategorie(resultats["Comics"], "Comics");
extraireIdsCategorie(resultats["Mangas"], "Mangas");

// 2. On parcourt TOUTES les listes pour fusionner les données (Titre et Chiffres)
const pagesAAnalyser = [resultats["Toutes"], resultats["BD"], resultats["Comics"], resultats["Mangas"]];

for (const p of pagesAAnalyser) {
    if (!p) continue;
    const morceaux = p.split('href="/');

    for (let i = 1; i < morceaux.length; i++) {
        const morceau = morceaux[i];
        if (!morceau.includes('serie/')) continue;

        const idMatch = morceau.match(/^[^\/]+\/serie\/([a-zA-Z0-9]+)"/);
        if (!idMatch) continue;
        const id_unique = idMatch[1];

        // On initialise la série si on ne l'a pas encore vue (ex: Les Romans)
        if (!seriesMap[id_unique]) {
            seriesMap[id_unique] = { id_unique: id_unique, categorie: "Autre", titre: "Titre inconnu", albums_manquants: 0 };
        }

        // On met à jour le titre seulement s'il est présent dans ce morceau de code
        const titreMatch = morceau.match(/fw-bold bb-medium-text-size pb-1">([^<]+)<\/div>/);
        if (titreMatch) {
            seriesMap[id_unique].titre = titreMatch[1].trim();
        }

        // On met à jour le vrai chiffre des manquants !
        const manquantsMatch = morceau.match(/bb-l-text-size">([0-9]+)<\/div>\s*<div>albums?\s+manquants?/);
        if (manquantsMatch) {
            seriesMap[id_unique].albums_manquants = parseInt(manquantsMatch[1], 10);
        }
    }
}

// On convertit notre dictionnaire infaillible en liste pour n8n
const seriesExtraites = Object.values(seriesMap);

return seriesExtraites.map(serie => ({ json: serie }));

