const series = $input.all().map(item => item.json);

// 1. Initialisation des compteurs (y compris "Autre")
const stats = {
    "BD": 0, 
    "Comics": 0, 
    "Mangas": 0, 
    "Autre": 0
};

// 2. On boucle sur toutes tes séries pour additionner les albums manquants
