    "BD - Manquants": stats["BD"],
    "Comics - Manquants": stats["Comics"],
    "Mangas - Manquants": stats["Mangas"],
    "Autre - Manquants": stats["Autre"]
};

// On renvoie la ligne prête à être expédiée !
return [{ json: ligneGoogleSheet }];

