const html = $input.first().json.Statistiques;
const stats = {};

// 1. EXTRACTION DES PAGES LUES
// On cherche le chiffre brut dans la classe bb-xl-text-size
const pagesMatch = html.match(/bb-xl-text-size">([0-9\s]+)<\/div><div[^>]*>pages lues/);
if (pagesMatch) {
    stats.pages_lues = parseInt(pagesMatch[1].replace(/\s/g, ''), 10);
}

// 2. EXTRACTION DE LA VALEUR DE LA COLLECTION
// On cherche le montant dans le style font-size: 3rem
const valeurMatch = html.match(/font-size: 3rem;">([^<]+)<\/div>/);
if (valeurMatch) {
    // Nettoyage : on enlève les espaces, le symbole €, et on remplace la virgule par un point
    let valeurBrute = valeurMatch[1].replace(/&nbsp;/g, '').replace('€', '').replace(/\s/g, '').replace(',', '.');
    stats.valeur_collection = parseFloat(valeurBrute);
}

// 3. EXTRACTION DU POIDS DE LA COLLECTION
// On cherche le texte directement dans la classe bb-xxl-text-size suivi de "kg"
const poidsMatch = html.match(/bb-xxl-text-size">([0-9.,\s]+)\s*kg<\/div>/);
if (poidsMatch) {
    // Nettoyage : on garde les chiffres et le point/virgule, puis on convertit
    let poidsBrut = poidsMatch[1].replace(/\s/g, '').replace(',', '.');
    stats.poids_collection = parseFloat(poidsBrut);
} else {
    stats.poids_collection = 0;
}

return [{ json: stats }];

